# 苏住房防汛C端（uni-app H5）本地 nginx 部署
# 构建产物：D:/repository/苏住房防汛C端/dist/build/h5
# 由 nginx.conf 的 include conf.d/*.conf 自动加载，无需改动主配置。
#
# 端口说明：原用 8103 + default_server，与 sites-enabled/昆山物管.conf（昆山G，
# listen 8103 server_name localhost）抢占，且 default_server 会让所有其它 Host
# 的 8103 请求都落到本服务上，影响昆山项目。故改到空闲端口 8095 并去掉 default_server。
server {
    listen 8095;
    server_name localhost;
    root "D:/repository/苏住房防汛C端/dist/build/h5";
    index index.html;
    charset utf-8;

    # 静态资源长缓存，index.html 强制不走缓存，避免发版后 chunk 404
    location ~* \.(js|css|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot|map)$ {
        expires 7d;
        add_header Cache-Control "public" always;
        access_log off;
        try_files $uri =404;
    }

    location = /index.html {
        expires -1;
        add_header Cache-Control "no-cache, no-store, must-revalidate";
    }

    # 反向代理：同源转发到 flood 服务(9610)，规避浏览器 CORS
    location /api-flood/ {
        proxy_pass http://127.0.0.1:9610/;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }

    # 反向代理：同源转发到鉴权/用户服务(9211)
    location /api-auth/ {
        proxy_pass http://127.0.0.1:9211/;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }

    # uni-app H5 使用 hash 路由，回退到 index.html 即可
    location / {
        try_files $uri $uri/ /index.html;
    }
}


"}]

