import { DatabaseSync } from "node:sqlite";
import fs from "node:fs";
const db=new DatabaseSync("D:/nginx-ui/database.db",{readOnly:true});
const names=new Set(db.prepare("SELECT path FROM sites WHERE deleted_at IS NULL").all().map(r=>r.path.split("\\").pop()));
// 收集 enabled + conf.d 中所有实际生效的 server 配置文件
